import sys
from collections import deque

def bfs_distance(tree, start):
    dist = [-1] * len(tree)
    dist[start] = 0
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for neighbor in tree[node]:
            if dist[neighbor] == -1:
                dist[neighbor] = dist[node] + 1
                queue.append(neighbor)
    return dist

def is_bipartite(graph, start):
    color = [-1] * len(graph)
    color[start] = 0
    queue = deque([start])
    while(queue):
        node = queue.popleft()
        for neighbor in graph[node]:
            if color[neighbor] == -1:
                color[neighbor] = 1 - color[node]
                queue.append(neighbor)
            elif color[neighbor] == color[node]:
                return False, []
    return True, [i+1 for i, c in enumerate(color) if c == 0], [i+1 for i, c in enumerate(color) if c ==1]

def min_k_good_graph(N, edges):
    tree = [[] for _ in range(N)]
    for u, v in edges:
        tree[u-1].append(v-1)
        tree[v-1].append(u-1)

    max_dist = 0
    for i in range(N):
        dist = bfs_distance(tree, i)
        max_dist = max(max_dist, max(dist))

    for k in range(1, max_dist + 1):
        graph = [[] for _ in range(N)]
        for u in range(N):
            for v in range(N):
                if u != v and bfs_distance(tree, u)[v] <= k:
                    graph[u].append(v)
        bipartite, U, V = is_bipartite(graph, 0)
        if bipartite:
            return k, U, V

    return -1, [], []

def main():
    import sys
    input = sys.stdin.read().split('\n')
    idx = 0
    T = int(input[idx])
    idx += 1
    results = []
    for _ in range(T):
        N = int(input[idx])
        idx += 1
        edges = [tuple(map(int, input[i].split())) for i in range(idx, idx + N - 1)]
        idx += N - 1
        k, U, V = min_k_good_graph(N, edges)
        results.append(f"{k}\n{' '.join(map(str, U))}\n{' '.join(map(str, V))}")
    print("\n".join(results))

if __name__ == "__main__":
    main()
